import { useEffect, useState } from 'react'
import type { RouteObject } from 'react-router'

function Home() {
  const [status, setStatus] = useState('checking')
  useEffect(() => {
    fetch('/healthz')
      .then((res) => setStatus(res.ok ? 'up' : 'down'))
      .catch(() => setStatus('down'))
  }, [])
  return (
    <main>
      <h1>notes</h1>
      <p>Server: {status}</p>
    </main>
  )
}

// The app's pages; main.tsx serves them under /app, tests through renderAt.
export const routes: RouteObject[] = [{ path: '/', element: <Home /> }]
import { render } from '@testing-library/react'
import { createMemoryRouter, RouterProvider } from 'react-router'
import { routes } from '../App'

// renderAt renders the app's routes at path, as the browser would under /app.
export function renderAt(path: string) {
  const router = createMemoryRouter(routes, { initialEntries: [path] })
  return { router, ...render(<RouterProvider router={router} />) }
}
import { vi } from 'vitest'

export type Reply = { status?: number; body?: unknown }

// mockFetch replaces fetch until the test ends: each call answers what
// reply returns for its method, path and Request (query, body), as JSON.
// 204 and 304 answer a null body, since a Response with those statuses may
// carry none.
export function mockFetch(reply: (method: string, path: string, req: Request) => Reply) {
  const fn = vi.fn(async (input: RequestInfo | URL, init?: RequestInit) => {
    const req = new Request(new URL(input instanceof Request ? input.url : String(input), 'http://localhost'), init)
    const { status = 200, body = null } = reply(req.method, new URL(req.url).pathname, req)
    if (status === 204 || status === 304) return new Response(null, { status })
    return new Response(JSON.stringify(body), { status, headers: { 'Content-Type': 'application/json' } })
  })
  vi.stubGlobal('fetch', fn)
  return fn
}
import { screen } from '@testing-library/react'
import { expect, test } from 'vitest'
import { mockFetch } from './test/fetch'
import { renderAt } from './test/render'

test('home shows the server up', async () => {
  const fetch = mockFetch((method, path) => (method === 'GET' && path === '/healthz' ? { body: { status: 'ok' } } : { status: 404 }))
  renderAt('/')
  expect(screen.getByRole('heading').textContent).toBe('notes')
  expect(await screen.findByText('Server: up')).toBeTruthy()
  expect(fetch).toHaveBeenCalledOnce()
})

test('home shows the server down', async () => {
  mockFetch(() => ({ status: 503 }))
  renderAt('/')
  expect(await screen.findByText('Server: down')).toBeTruthy()
  expect(screen.getAllByRole('heading')).toHaveLength(1)
})
