+package server
+
+import (
+	"encoding/json"
+	"errors"
+	"io"
+	"net/http"
+	"regexp"
+	"strconv"
+	"strings"
+	"unicode/utf8"
+
+	"git.aisoftwarefactory.world/notes/notes/internal/store"
+)
+
+// The limits a note is kept within.
+const (
+	maxTitleLen = 200
+	maxBodyLen  = 20000
+	maxTags     = 10
+)
+
+// maxNoteBodyBytes bounds the request body: the JSON of a note at its
+// longest title and body, with room for ten tags and their quotes.
+const maxNoteBodyBytes = 64 << 10
+
+// tagPattern is what a tag is after lower-casing and trimming.
+var tagPattern = regexp.MustCompile(`^[a-z0-9-]{1,30}$`)
+
+// noteRequest is the JSON a create or an update carries. Tags are nil when
+// the request names none: an update then keeps the note's own tags.
+type noteRequest struct {
+	Title string   `json:"title"`
+	Body  string   `json:"body"`
+	Tags  []string `json:"tags"`
+}
+
+// noteJSON is a note as the API answers it. Times are UTC RFC 3339.
+type noteJSON struct {
+	ID        int64    `json:"id"`
+	Title     string   `json:"title"`
+	Body      string   `json:"body"`
+	Tags      []string `json:"tags"`
+	Pinned    bool     `json:"pinned"`
+	CreatedAt string   `json:"created_at"`
+	UpdatedAt string   `json:"updated_at"`
+}
+
+func noteToJSON(n *store.Note) noteJSON {
+	return noteJSON{
+		ID:        n.ID,
+		Title:     n.Title,
+		Body:      n.Body,
+		Tags:      n.Tags,
+		Pinned:    n.Pinned,
+		CreatedAt: n.CreatedAt.UTC().Format(timeRFC3339),
+		UpdatedAt: n.UpdatedAt.UTC().Format(timeRFC3339),
+	}
+}
+
+// registerNotes puts the note CRUD and the tag listing on the mux. Every
+// route runs behind apiAuth, so the user is the one the guard named.
+func (s *server) registerNotes(mux *http.ServeMux) {
+	mux.HandleFunc("POST /api/notes", s.createNote)
+	mux.HandleFunc("GET /api/notes/{id}", s.getNote)
+	mux.HandleFunc("PUT /api/notes/{id}", s.updateNote)
+	mux.HandleFunc("DELETE /api/notes/{id}", s.deleteNote)
+	mux.HandleFunc("GET /api/tags", s.listTags)
+}
+
+// validateNote checks the title, the body and the tags of a request, and
+// returns the tags normalised: lower-cased, trimmed, without duplicates.
+// It answers what is wrong, or nil when nothing is.
+func validateNote(req *noteRequest) ([]string, map[string]string) {
+	details := map[string]string{}
+	title := strings.TrimSpace(req.Title)
+	switch {
+	case title == "":
+		details["title"] = "must not be empty"
+	case utf8.RuneCountInString(title) > maxTitleLen:
+		details["title"] = "must be at most 200 characters"
+	}
+	if utf8.RuneCountInString(req.Body) > maxBodyLen {
+		details["body"] = "must be at most 20000 characters"
+	}
+
+	tags := make([]string, 0, len(req.Tags))
+	seen := make(map[string]bool, len(req.Tags))
+	for i, raw := range req.Tags {
+		tag := strings.ToLower(strings.TrimSpace(raw))
+		name := "tags[" + strconv.Itoa(i) + "]"
+		switch {
+		case tag == "":
+			details[name] = "must not be empty"
+		case !tagPattern.MatchString(tag):
+			details[name] = "must match [a-z0-9-]{1,30} after lower-casing"
+		}
+		if seen[tag] {
+			continue
+		}
+		seen[tag] = true
+		tags = append(tags, tag)
+	}
+	if len(req.Tags) > maxTags {
+		details["tags"] = "must be at most 10"
+	} else if len(tags) > maxTags {
+		// Ten distinct tags hidden among eleven that are not valid would
+		// otherwise pass on the count of the request alone.
+		details["tags"] = "must be at most 10"
+	}
+	if len(details) > 0 {
+		return nil, details
+	}
+	return tags, nil
+}
+
+// decodeNote reads the request's JSON. A body that is not a JSON object is
+// a 400 with its own detail; anything the store rejects is a 500.
+func decodeNote(w http.ResponseWriter, r *http.Request) (*noteRequest, bool) {
+	body, err := io.ReadAll(io.LimitReader(r.Body, maxNoteBodyBytes+1))
+	if err != nil {
+		writeValidationError(w, map[string]string{"body": "could not be read"})
+		return nil, false
+	}
+	if len(body) > maxNoteBodyBytes {
+		writeValidationError(w, map[string]string{"body": "request entity too large"})
+		return nil, false
+	}
+	req := &noteRequest{}
+	if len(strings.TrimSpace(string(body))) == 0 {
+		writeValidationError(w, map[string]string{"body": "must be a JSON object"})
+		return nil, false
+	}
+	dec := json.NewDecoder(strings.NewReader(string(body)))
+	dec.DisallowUnknownFields()
+	if err := dec.Decode(req); err != nil {
+		writeValidationError(w, map[string]string{"body": "must be a JSON object: " + err.Error()})
+		return nil, false
+	}
+	return req, true
+}
+
+func writeValidationError(w http.ResponseWriter, details map[string]string) {
+	writeJSON(w, http.StatusBadRequest, map[string]any{"error": "invalid note", "details": details})
+}
+
+func (s *server) createNote(w http.ResponseWriter, r *http.Request) {
+	userID, ok := userIDFrom(r)
+	if !ok {
+		writeJSON(w, http.StatusUnauthorized, map[string]string{"error": "unauthorized"})
+		return
+	}
+	req, ok := decodeNote(w, r)
+	if !ok {
+		return
+	}
+	tags, details := validateNote(req)
+	if details != nil {
+		writeValidationError(w, details)
+		return
+	}
+	note, err := s.store.CreateNote(userID, strings.TrimSpace(req.Title), req.Body, tags)
+	if err != nil {
+		writeStoreError(w, err)
+		return
+	}
+	writeJSON(w, http.StatusCreated, noteToJSON(note))
+}
+
+// noteIDFrom answers the {id} of the path; a value that is no positive
+// number is 404, since no note can carry it.
+func noteIDFrom(w http.ResponseWriter, r *http.Request) (int64, bool) {
+	id, err := strconv.ParseInt(r.PathValue("id"), 10, 64)
+	if err != nil || id < 1 {
+		writeJSON(w, http.StatusNotFound, map[string]string{"error": "not found"})
+		return 0, false
+	}
+	return id, true
+}
+
+func (s *server) getNote(w http.ResponseWriter, r *http.Request) {
+	userID, _ := userIDFrom(r)
+	noteID, ok := noteIDFrom(w, r)
+	if !ok {
+		return
+	}
+	note, err := s.store.GetNote(noteID, userID)
+	if err != nil {
+		writeStoreError(w, err)
+		return
+	}
+	writeJSON(w, http.StatusOK, noteToJSON(note))
+}
+
+func (s *server) updateNote(w http.ResponseWriter, r *http.Request) {
+	userID, _ := userIDFrom(r)
+	noteID, ok := noteIDFrom(w, r)
+	if !ok {
+		return
+	}
+	req, ok := decodeNote(w, r)
+	if !ok {
+		return
+	}
+	tags, details := validateNote(req)
+	if details != nil {
+		writeValidationError(w, details)
+		return
+	}
+	current, err := s.store.GetNote(noteID, userID)
+	if err != nil {
+		writeStoreError(w, err)
+		return
+	}
+	if req.Tags == nil {
+		tags = current.Tags
+	}
+	note, err := s.store.UpdateNote(noteID, userID, strings.TrimSpace(req.Title), req.Body, tags)
+	if err != nil {
+		writeStoreError(w, err)
+		return
+	}
+	writeJSON(w, http.StatusOK, noteToJSON(note))
+}
+
+func (s *server) deleteNote(w http.ResponseWriter, r *http.Request) {
+	userID, _ := userIDFrom(r)
+	noteID, ok := noteIDFrom(w, r)
+	if !ok {
+		return
+	}
+	if err := s.store.DeleteNote(noteID, userID); err != nil {
+		writeStoreError(w, err)
+		return
+	}
+	w.WriteHeader(http.StatusNoContent)
+}
+
+// tagCountJSON is one of the user's tags with how many of their notes carry it.
+type tagCountJSON struct {
+	Tag   string `json:"tag"`
+	Count int    `json:"count"`
+}
+
+func (s *server) listTags(w http.ResponseWriter, r *http.Request) {
+	userID, _ := userIDFrom(r)
+	counts, err := s.store.ListTags(userID)
+	if err != nil {
+		writeStoreError(w, err)
+		return
+	}
+	out := make([]tagCountJSON, 0, len(counts))
+	for _, tc := range counts {
+		out = append(out, tagCountJSON{Tag: tc.Tag, Count: tc.Count})
+	}
+	writeJSON(w, http.StatusOK, map[string]any{"tags": out})
+}
+
+// writeStoreError answers the store's failure: a note that is not there, or
+// not the caller's, is 404; anything else is 500 and goes to the log.
+func writeStoreError(w http.ResponseWriter, err error) {
+	if errors.Is(err, store.ErrNotFound) {
+		writeJSON(w, http.StatusNotFound, map[string]string{"error": "not found"})
+		return
+	}
+	writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "internal error"})
+}

