+// noteRequest is the JSON a create or an update carries. Tags are nil when
+// the request names none: an update then keeps the note's own tags.
+type noteRequest struct {
+	Title string   `json:"title"`
+	Body  string   `json:"body"`
+	Tags  []string `json:"tags"`
+}
