+	ID        int64    `json:"id"`
+	Title     string   `json:"title"`
+	Body      string   `json:"body"`
+	Tags      []string `json:"tags"`
+	Pinned    bool     `json:"pinned"`
+	CreatedAt string   `json:"created_at"`
+	UpdatedAt string   `json:"updated_at"`
+}
+
+func noteToJSON(n *store.Note) noteJSON {
+	return noteJSON{
+		ID:        n.ID,
+		Title:     n.Title,
+		Body:      n.Body,
+		Tags:      n.Tags,
+		Pinned:    n.Pinned,
+		CreatedAt: n.CreatedAt.UTC().Format(timeRFC3339),
+		UpdatedAt: n.UpdatedAt.UTC().Format(timeRFC3339),
+	}
+}
+
+// registerNotes puts the note CRUD and the tag listing on the mux. Every
+// route runs behind apiAuth, so the user is the one the guard named.
+func (s *server) registerNotes(mux *http.ServeMux) {
